// Generated by frontend/scripts/build-public-site.js: the landing page's light/dark switch.
(function () {
  var root = document.documentElement;
  var KEY = "lately-theme";
  var dark = window.matchMedia("(prefers-color-scheme: dark)");
  try {
    var saved = localStorage.getItem(KEY);
    if (saved === "light" || saved === "dark") root.setAttribute("data-theme", saved);
  } catch (e) {}
  function current() {
    return root.getAttribute("data-theme") || (dark.matches ? "dark" : "light");
  }
  document.addEventListener("DOMContentLoaded", function () {
    var button = document.querySelector(".theme-toggle");
    if (!button) return;
    function label() {
      button.setAttribute("aria-label", current() === "dark" ? "Switch to light mode" : "Switch to dark mode");
    }
    button.addEventListener("click", function () {
      var next = current() === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      try { localStorage.setItem(KEY, next); } catch (e) {}
      label();
    });
    if (dark.addEventListener) dark.addEventListener("change", label);
    label();
    button.hidden = false;
  });
})();
